import sys

def main():
    n = int(sys.stdin.readline())
    degree = [0] * (n + 1)

    for _ in range(n - 1):
        a, b = map(int, sys.stdin.readline().split())
        degree[a] += 1
        degree[b] += 1

    count = 0
    for i in range(1, n + 1):
        d = degree[i]
        if d >= 2:
            count += d * (d - 1) // 2

    print(count)

if __name__ == "__main__":
    main()
