def get_divisors(s):
    n = len(s)
    divisors = set()

    # Check all possible lengths that divide n
    for i in range(1, n + 1):
        if n % i == 0:
            # Check if substring of length i is a divisor
            candidate = s[:i]
            if all(s[j:i] == candidate for j in range(i, n, i)):
                divisors.add(candidate)

    return divisors


def main():
    s1 = input().strip()
    s2 = input().strip()

    divisors_s1 = get_divisors(s1)
    divisors_s2 = get_divisors(s2)

    # Find common divisors
    common_divisors = divisors_s1.intersection(divisors_s2)

    print(len(common_divisors))

if __name__ == "__main__":
    main()
"}

