def solve():
    n = int(input())
    angles = [int(input()) for _ in range(n)]
    total = sum(angles)

    # For the pointer to return to 0, total must be even
    if total % 2 != 0:
        print("NO")
        return

    # Use brute force to check all possible assignments
    # Each angle can be either +a_i or -a_i
    # We need to check if any combination sums to 0 mod 360

    # Brute force with bitmask (n ≤ 15, so 2^15 = 32768 iterations)
    for mask in range(1 << n):
        current_sum = 0
        for i in range(n):
            if mask & (1 << i):
                current_sum += angles[i]  # clockwise
            else:
                current_sum -= angles[i]  # counterclockwise
        if current_sum % 360 == 0:
            print("YES")
            return
    print("NO")

solve()
