import sys

def minimal_perimeter(a, b):
    # Total area
    total_area = a + b

    # Try all possible dimensions for the total rectangle
    min_perimeter = float('inf')

    # We'll try all possible widths
    for width in range(1, int(total_area**0.5) + 1):
        if total_area % width == 0:
            height = total_area // width
        else:
            height = total_area // width + 1

        # Check if at least one color can form a rectangle
        # Check if red can form a rectangle
        red_possible = False
        for r_width in range(1, int(a**0.5) + 1):
            if a % r_width == 0:
                r_height = a // r_width
                if r_width <= width and r_height <= height:
                    red_possible = True
                    break

        # Check if blue can form a rectangle
        blue_possible = False
        for b_width in range(1, int(b**0.5) + 1):
            if b % b_width == 0:
                b_height = b // b_width
                if b_width <= width and b_height <= height:
                    blue_possible = True
                    break

        if red_possible or blue_possible:
            perimeter = 2 * (width + height)
            if perimeter < min_perimeter:
                min_perimeter = perimeter

    return min_perimeter

if __name__ == "__main__":
    a, b = map(int, sys.stdin.read().split())
    print(minimal_perimeter(a, b))
"}

