    # Try all possible dimensions for the large rectangle
    min_perimeter = float('inf')

    # Try all possible factor pairs for the total area
    for m in range(1, int(total**0.5) + 1):
        if total % m == 0:
            n = total // m

            # Check if a has any divisor <= m
            has_divisor_a = False
            for w in range(1, int(a**0.5) + 1):
                if a % w == 0:
                    if w <= m:
                        has_divisor_a = True
                        break

            # Check if b has any divisor <= m
            has_divisor_b = False
            for x in range(1, int(b**0.5) + 1):
                if b % x == 0:
                    if x <= m:
                        has_divisor_b = True
                        break

            if has_divisor_a and has_divisor_b:
                perimeter = 2 * (m + n)
                if perimeter < min_perimeter:
                    min_perimeter = perimeter

    return min_perimeter

