        # Then we need: x*(x-1)//2 = a00
        #                  (y-i)*(y-i-1)//2 = a11
        #                  i*x = a01

        if a01 % x == 0:
            i = a01 // x

            # We need at least i ones
            if i > 1000:
                break

            # Find y such that (y-i)*(y-i-1)//2 = a11
            for y in range(i, 1000):
                if y == i:
                    # Need at least 2 ones after i
                    if a11 == 0:
                        print('1' * i + '0' * x)
                        return
                    continue

                val = (y-i)*(y-i-1)//2
                if val == a11:
                    # Check if we can form the string
                    # First i ones, then x zeros, then y-i ones
                    # Number of '00': x*(x-1)//2
                    if x*(x-1)//2 == a00:
                        print('1'*i + '0'*x + '1'*(y-i))
