# Function to compute square-free representation
# Returns the square-free part of a number
def square_free(n):
    i = 2
    result = n

    while i * i <= n:
        # Count how many times i divides n
        count = 0
        while n % i == 0:
            count += 1
            n //= i

        # If count is odd, keep i in square-free representation
        if count % 2 == 1:
            result //= i

        i += 1

    return result

# Compute square-free representation for each number
square_free_counts = {}

for num in a:
    sf = square_free(num)
    if sf == 1:
        # Found a perfect square
        print(1)
        exit()

    if sf in square_free_counts:
        square_free_counts[sf] += 1
    else:
        square_free_counts[sf] = 1

# Check for duplicate square-free representations
for count in square_free_counts.values():
    if count >= 2:
        print(2)
        exit()

