import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    p = list(map(int, data[1:1+n]))

    # Build adjacency list
    graph = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        parent = p[i - 1]
        if parent == 0:
            parent = i  # root has no parent, degree 0
        graph[i].append(parent)
        graph[parent].append(i)

    # Compute degrees
    degrees = [0] * (n + 1)
    for i in range(1, n + 1):
        degrees[i] = len(graph[i])

    # If n is odd, it's possible
    if n % 2 == 0:
        print("NO")
    else:
        print("YES")

        # Construct destruction order
        # Strategy: DFS from root, destroying vertices
        visited = [False] * (n + 1)
        order = []

        def dfs(v):
            # We can destroy a vertex if its degree is even
            if degrees[v] % 2 == 0:
                visited[v] = True
                order.append(v)
                for neighbor in graph[v]:
                    if not visited[neighbor]:
                        dfs(neighbor)
            else:
                # We can't destroy this vertex yet
                pass

        # Start DFS from root (vertex with parent 0)
        root = 0
        for i in range(1, n + 1):
            if p[i - 1] == 0:
                root = i
                break

        dfs(root)

        # Print order
        for idx, vertex in enumerate(order, 1):
            print(idx, vertex)

if __name__ == "__main__":
    solve()
