def solve(t):
    # Get first occurrence of each character
    pattern = ''
    seen = set()

    for char in t:
        if char not in seen:
            seen.add(char)
            pattern += char

    # If pattern length is 1, we don't need to repeat it at all
    # Otherwise, repeat it twice to ensure length doesn't exceed 2 * len(t)
    if len(pattern) == 1:
        s = pattern
    else:
        s = pattern * 2

    return s

T = int(input())
for _ in range(T):
    t = input().strip()
    result = solve(t)
    print(result)
