def is_perfect_cube(n):
    if n == 0:
        return False
    cube_root = round(n ** (1/3))
    # Check if cube_root^3 == n
    if cube_root ** 3 == n:
        return True
    # Check if (cube_root - 1)^3 == n or (cube_root + 1)^3 == n
    if (cube_root - 1) ** 3 == n:
