def solve():
    import sys
    input = sys.stdin.read().splitlines()

    if not input:
        return

    # Parse first line
    first_line = input[0].strip().split()
    if not first_line:
        return

    n = int(first_line[0])
    m = int(first_line[1])
    t = int(first_line[2])

    # Read grid
    grid = []
    for i in range(1, 1 + n):
        row = input[i].strip()
        # Convert binary string to list of integers
        grid.append([int(ch) for ch in row])

    # Read queries
    queries = []
    query_idx = 1 + n
    for _ in range(t):
        if query_idx >= len(input):
            break
        line = input[query_idx].strip().split()
        if not line:
            query_idx += 1
            continue

        i = int(line[0]) - 1
        j = int(line[1]) - 1
        p = int(line[2])
        queries.append((i, j, p))

        query_idx += 1

    # Precompute color for each cell after each iteration
    # We'll simulate until we reach iteration p or until stable

    # Create a copy of grid to simulate
    sim_grid = [row[:] for row in grid]

    # Dictionary to store color at each cell for each iteration
    color_at = {}

    for i in range(n):
        for j in range(m):
            color_at[(i, j)] = [sim_grid[i][j]]

    # Simulate until we reach iteration p or until stable
    for iteration in range(p):
        # Create new grid
        new_grid = [row[:] for row in sim_grid]

        # Update each cell
        for i in range(n):
            for j in range(m):
                val = sim_grid[i][j]
                same_neighbor = False

                # Check adjacent cells
                for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m and sim_grid[ni][nj] == val:
                        same_neighbor = True
                        break

                if not same_neighbor:
                    # Stay the same
                    new_val = val
                else:
                    # Flip
                    new_val = 1 - val

                new_grid[i][j] = new_val

        # Check if the grid has changed
        changed = False
        for i in range(n):
            for j in range(m):
                if new_grid[i][j] != sim_grid[i][j]:
                    changed = True
                    break
            if changed:
                break

        if not changed:
            # Grid is stable, all cells will stay the same
            break

        # Update the simulation
        sim_grid = new_grid

        # Record colors for queries that have reached this iteration
        for i in range(n):
            for j in range(m):
                color_at[(i, j)].append(sim_grid[i][j])

    # Process queries
    for i, j, p in queries:
        # Get the color at iteration p
        if p <= len(color_at[(i, j)]) - 1:
            # We have computed this iteration
            color = color_at[(i, j)][p]
        else:
            # After the grid stabilized, it stays the same
            color = color_at[(i, j)][-1]

        print(str(color))

if __name__ == "__main__":
