def solve():
    n, m, t = map(int, input().split())

    # Read initial grid
    grid = []
    for _ in range(n):
        grid.append(input().strip())

    # For each cell, store the color at each iteration
    color_at_iter = {}  # Maps (i, j) to list of colors at different iterations

    # First, we have the initial grid at iteration 0
    for i in range(n):
        for j in range(m):
            color_at_iter[(i, j)] = [int(grid[i][j])]

    # Simulate until we see stabilization or a repeat for each cell
    max_simulate = 100  # We'll simulate up to 100 iterations to find patterns
    for _ in range(max_simulate):
        current_grid = [[0] * m for _ in range(n)]

        # Compute next grid
        for i in range(n):
            for j in range(m):
                current_color = color_at_iter[(i, j)][-1]

                # Determine neighbors
                same_color_neighbors = 0
                for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < n and 0 <= nj < m:
                        neighbor_color = color_at_iter[(ni, nj)][-1]
                        if neighbor_color == current_color:
                            same_color_neighbors += 1

                # Apply the rule
                if same_color_neighbors == 0:
                    # Color stays the same
                    current_grid[i][j] = current_color
                else:
                    # Color flips
                    current_grid[i][j] = 1 - current_color

        # Store the new colors
        for i in range(n):
            for j in range(m):
                color_at_iter[(i, j)].append(current_grid[i][j])

    # Now answer queries
    for _ in range(t):
        i, j, p = map(int, input().split())
        i -= 1  # Convert to 0-indexed
        j -= 1

        # Get the color at iteration p
        # We have up to 100 iterations; if p > 100, we need to find the pattern
        # Since the process stabilizes, the color might be the same as the final one
        if p <= len(color_at_iter[(i, j)]):
            print(color_at_iter[(i, j)][p-1])
        else:
            # After the last simulated iteration, the color might stabilize
            # So we just return the final color
            print(color_at_iter[(i, j)][-1])

