def longest_common_subsequence(n, k, permutations):
    """Find the length of the longest common subsequence across all permutations"""
    # For each number, store its positions in all k permutations
    positions = {}
    for i, perm in enumerate(permutations):
        for num, pos in enumerate(perm, 1):
            positions[num] = positions.get(num, []) + [pos]

    # Create a list of tuples: (number, position tuple)
    number_positions = [(num, tuple(positions[num])) for num in range(1, n+1)]

    # Sort by position tuples (lexicographical order)
    number_positions.sort(key=lambda x: x[1])

    # Now find the longest increasing subsequence
    # We want the longest sequence where each next tuple is strictly greater
    dp = [1] * n  # dp[i] = length of LCS ending with number i+1

    for i in range(n):
        for j in range(i):
            prev_positions = number_positions[j][1]
            curr_positions = number_positions[i][1]
            # Check if curr_positions is strictly greater than prev_positions
            if all(curr > prev for curr, prev in zip(curr_positions, prev_positions)):
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

