def solve()
    n, k = map(int, input().split())
    perms = []
    for _ in range(k):
        perms.append(list(map(int, input().split())))

    # For each position in the first permutation, find the length of the longest common subsequence
    # starting at that position
    max_len = 0

    # Create a position map for each number in each permutation
    pos = {}
    for p in perms:
        pos[p] = {}
        for i, num in enumerate(p):
            pos[p][num] = i

    # Use dynamic programming where dp[i] = length of longest common subsequence starting at position i in permutation 1
    dp = [1] * n  # Base case: minimum length is 1

    # For each starting position in permutation 1
    for start in range(n):
        # For each element that appears after start in permutation 1
        for i in range(start + 1, n):
            num = perms[0][i]

            # Check if num appears after the current position in all other permutations
            extend = True
            for p in perms[1:]:
                if pos[p][num] <= pos[p][perms[0][start]]:
                    extend = False
                    break

            if extend:
                dp[start] = max(dp[start], 1 + dp[i])

    print(max(dp))

