def can_reach_zero(a, n):
    """Check if we can reach 0 from a given starting position with the given rotations"""

    # We need to check all possible combinations of clockwise/counterclockwise rotations
    # This is a classic subset sum problem with two choices for each element

    # We can use a recursive approach with memoization or a simple backtracking

    # Let's use a recursive approach

    def backtrack(index, current):
        # Base case: if we've processed all rotations
        if index == n:
            # Check if current position is 0 mod 360
            return current % 360 == 0

        # Try clockwise rotation
        if backtrack(index + 1, (current + a[index]) % 360):
            return True

        # Try counterclockwise rotation
        if backtrack(index + 1, (current - a[index]) % 360):
            return True

        return False

    return backtrack(0, 0)

# Read input
