import math

def get_divisors(n):
    """Get all divisors of a number"""
    divisors = []
    for i in range(1, n + 1):
        if n % i == 0:
            divisors.append(i)
    return divisors

def is_divisor(s, divisor):
    """Check if 'divisor' is a divisor of string 's'"""
    divisor_len = len(divisor)
    if len(s) % divisor_len != 0:
        return False
    # Check if repeating divisor forms s
    return s == divisor * (len(s) // divisor_len)

def main():
    s1 = input().strip()
    s2 = input().strip()

    len1 = len(s1)
    len2 = len(s2)

    # Find GCD of the lengths
    gcd_len = math.gcd(len1, len2)

    # Get all divisors of the GCD length
    common_lengths = get_divisors(gcd_len)

    # Check which of these lengths are common divisors
    count = 0
    for length in common_lengths:
        candidate = s1[:length]  # Take prefix of this length
        if is_divisor(s1, candidate) and is_divisor(s2, candidate):
            count += 1

    print(count)

if __name__ == "__main__":
    main()
"}

