import sys

def get_path_cost(u, v, fees):
    """Calculate the total fee for the shortest path from u to v"""
    cost = 0
    while u != v:
        if u > v:
            # Move u up to its parent
            if u in fees:
                cost += fees[u]
            u //= 2
        else:
            # Move v up to its parent
            if v in fees:
                cost += fees[v]
            v //= 2
    return cost

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    q = int(data[0])
    idx = 1

    fees = {}

    for _ in range(q):
        if data[idx] == '1':
            # Update event
            v = int(data[idx+1])
            u = int(data[idx+2])
            w = int(data[idx+3])

            # Find path and update fees
            current_v = v
            current_u = u
            while current_v != current_u:
                if current_v > current_u:
                    if current_v in fees:
                        fees[current_v] += w
                    else:
                        fees[current_v] = w
                    current_v //= 2
                else:
                    if current_u in fees:
                        fees[current_u] += w
                    else:
                        fees[current_u] = w
                    current_u //= 2

            idx += 4
        else:
            # Query event
            v = int(data[idx+1])
            u = int(data[idx+2])

            # Calculate and print cost
            print(get_path_cost(v, u, fees))

            idx += 3

if __name__ == "__main__":
    main()
"}

