import sys

def get_path_cost(u, v, fees):
    """Calculate the total fee for the shortest path from u to v"""
    cost = 0
    while u != v:
        if u > v:
            # Move u up to its parent
            if u in fees:
                cost += fees[u]
            u //= 2
        else:
            # Move v up to its parent
            if v in fees:
                cost += fees[v]
            v //= 2
    return cost

def main():
