    if count == 4:
        leg_length = length
        break

# Check if we can make a bear or elephant
if leg_length is not None:
    # Get remaining sticks (those not used for legs)
    remaining = []
    for length, count in freq.items():
        if length == leg_length:
            continue
        for _ in range(count):
            remaining.append(length)

    # Sort remaining sticks
    remaining.sort()

    # Check bear: head < body
    if remaining[0] < remaining[1]:
        print("Bear")
    # Check elephant: head == body
    elif remaining[0] == remaining[1]:
        print("Elephant")
    else:
        print("Alien")
else:
    print("Alien")
