def find_min_number(n):
    if n == 1:
        return -1

    # Find the smallest number of length n that is divisible by 210

    # The smallest number of length n is 10^(n-1)
    # We need to find the smallest number >= 10^(n-1) divisible by 210

    # Instead of computing 10^(n-1), we compute its remainder modulo 210

    # 10^k mod 210
    # 210 = 2 * 3 * 5 * 7
    # We need 10^(n-1) mod 210

    # Since 10 and 210 are not coprime, we can't use Euler's theorem
    # But we can compute it directly using modular exponentiation

    remainder = pow(10, n-1, 210)

    # Find the smallest number >= 10^(n-1) divisible by 210
    if remainder == 0:
        return 10 ** (n-1)
    else:
        return 10 ** (n-1) + (210 - remainder)

