number_positions.sort()

# Use DP to find the longest increasing subsequence in k-1 dimensions
# (we already sorted by the first dimension, so it's always increasing)
def lis_kdim(arr, k):
    """Find the length of the longest increasing subsequence in k dimensions."""
    n = len(arr)
    dp = [1] * n
    prev = [-1] * n

    for i in range(n):
        for j in range(i):
            # Check if we can extend the LIS ending at j to include i
            can_extend = True
            for d in range(k):
                if arr[j][d] >= arr[i][d]:
                    can_extend = False
                    break

            if can_extend and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
                prev[i] = j

    return max(dp)

# Find the LIS in k-1 dimensions
result = lis_kdim(number_positions, k - 1)
