# Precompute smallest prime factors (SPF)
max_val = max(a)
spf = list(range(max_val + 1))
for i in range(2, int(max_val**0.5) + 1):
    if spf[i] == i:
        for j in range(i*i, max_val + 1, i):
            if spf[j] == j:
                spf[j] = i

# Function to get prime factors and their exponents
def get_factors(x):
    factors = {}
    while x > 1:
        p = spf[x]
        count = 0
        while x % p == 0:
            count += 1
            x //= p
        factors[p] = count
    return factors

# Function to get signature (bitmask of primes with odd exponents)
def get_signature(x):
    factors = get_factors(x)
    signature = 0
    # Prime indices: we need to assign each prime a unique bit position
    # We'll use a dictionary to map primes to bits
    prime_to_bit = {}
    bit = 0
    for p in factors:
        if p not in prime_to_bit:
            prime_to_bit[p] = bit
            bit += 1
    for p in factors:
        if factors[p] % 2 == 1:
            signature |= 1 << prime_to_bit[p]
    return signature

# Use BFS to find shortest subsequence with XOR = 0
from collections import deque

# Map from number to its signature
num_to_sig = {}
for num in a:
    sig = get_signature(num)
    num_to_sig[num] = sig

# BFS
visited = {}
queue = deque([(0, 0)])  # (mask, length)
visited[0] = 0

while queue:
    mask, length = queue.popleft()
    for num, sig in num_to_sig.items():
        new_mask = mask ^ sig
        new_length = length + 1
        if new_mask == 0:
            print(new_length)
            exit()
        if new_mask not in visited or new_length < visited[new_mask]:
            visited[new_mask] = new_length
            queue.append((new_mask, new_length))

print(-1)
