    rows = []
    for _ in range(n):
        line = input().strip()
        col_indices = [i for i, ch in enumerate(line) if ch == '1']
        if col_indices:
            rows.append(set(col_indices))

    # For each possible subarray (contiguous block of rows), compute the intersection
    max_area = 0

    # Use a sliding window approach on the subarrays
    for left in range(len(rows)):
        intersection = rows[left].copy()
        for right in range(left, len(rows)):
            if not intersection.intersection(rows[right]):
                break
            intersection &= rows[right]
            area = (right - left + 1) * len(intersection)
            max_area = max(max_area, area)

