MOD = 10**9 + 7

n = int(input())
s = input()

length = 2 * n
s_len = len(s)

# DP for counting regular bracket sequences
dp_reg = [[0] * (length + 1) for _ in range(length + 1)]
dp_reg[0][0] = 1

for i in range(length):
    for bal in range(length + 1):
        if dp_reg[i][bal] == 0:
            continue

        # Add '('
        if bal + 1 <= length:
            dp_reg[i+1][bal+1] = (dp_reg[i+1][bal+1] + dp_reg[i][bal]) % MOD

        # Add ')'
        if bal > 0 and bal - 1 <= length:
            dp_reg[i+1][bal-1] = (dp_reg[i+1][bal-1] + dp_reg[i][bal]) % MOD

# DP for inclusion/exclusion with substring s
# dp2[i][d][k]: number of sequences of length i with balance d, and the last k characters match s
dp2 = [[[0] * (s_len + 1) for _ in range(length + 1)] for _ in range(length + 1)]
dp2[0][0][0] = 1

for i in range(length):
    for bal in range(length + 1):
        for last_k in range(s_len + 1):
            if dp2[i][bal][last_k] == 0:
                continue

            # Try adding '('
            new_bal = bal + 1
            new_last_k = last_k
            if new_last_k < s_len and s[new_last_k] == '(':
                new_last_k += 1

            # Don't access s[new_last_k] when we've matched all of s
            if new_last_k < s_len:
                dp2[i+1][new_bal][new_last_k] = (dp2[i+1][new_bal][new_last_k] + dp2[i][bal][last_k]) % MOD
            else:
                # If we've matched all of s, we should consider sequences that contain s
                # So we can consider sequences that end with the matched s
                dp2[i+1][new_bal][s_len] = (dp2[i+1][new_bal][s_len] + dp2[i][bal][last_k]) % MOD

            # Try adding ')'
            new_bal = bal - 1
            new_last_k = last_k
            if new_bal >= 0 and new_last_k < s_len and s[new_last_k] == ')':
                new_last_k += 1

