            else:
                dp2[i+1][new_bal][s_len] = (dp2[i+1][new_bal][s_len] + dp2[i][bal][last_k]) % MOD

answer = (dp_reg[length][0] - dp2[length][0][s_len]) % MOD
print(answer)
