                non_multiples.append(x)

        # Check if non-multiples are in non-decreasing order
        non_multiples_sorted = sorted(non_multiples)
        non_multiples_in_order = True
        for i in range(len(non_multiples) - 1):
            if non_multiples[i] > non_multiples[i+1]:
                non_multiples_in_order = False
                break

        # Check if there are at least two multiples of m
        multiples_count = n - len(non_multiples)
        can_sort_multiples = multiples_count >= 2

        if non_multiples_in_order and can_sort_multiples:
            print("YES")
        else:
            print("NO")

