import math

def minimal_perimeter(a, b):
    """Find the minimal perimeter of a rectangle containing a+b colored tiles, where one color forms a rectangle."""

    min_perimeter = float('inf')

    # Try all possible ways to place red tiles in a rectangle
    for w_red in range(1, int(math.isqrt(a)) + 1):
        if a % w_red == 0:
            h_red = a // w_red
            # Red tiles occupy w_red x h_red sub-rectangle
            # Blue tiles occupy the remaining area
            # We need w * h >= a + b
            for w_total in range(w_red, int(math.isqrt(a + b)) + 1):
                for h_total in range(h_red, int(math.isqrt(a + b)) + 1):
                    if w_total * h_total >= a + b:
                        # Check if blue tiles can fit in the remaining area
                        # The remaining area has dimensions max(w_total, w_red) x max(h_total, h_red)
                        # Actually, we need to check if there's enough space for blue tiles
                        # The remaining area after placing red tiles is at least
                        # (w_total * h_total - w_red * h_red) = b
                        if w_total * h_total - w_red * h_red >= b:
                            perimeter = 2 * (w_total + h_total)
                            min_perimeter = min(min_perimeter, perimeter)

    # Try all possible ways to place blue tiles in a rectangle
    for w_blue in range(1, int(math.isqrt(b)) + 1):
        if b % w_blue == 0:
            h_blue = b // w_blue
            for w_total in range(w_blue, int(math.isqrt(a + b)) + 1):
                for h_total in range(h_blue, int(math.isqrt(a + b)) + 1):
                    if w_total * h_total >= a + b:
                        if w_total * h_total - w_blue * h_blue >= a:
                            perimeter = 2 * (w_total + h_total)
                            min_perimeter = min(min_perimeter, perimeter)

    return min_perimeter

a, b = map(int, input().split())
print(minimal_perimeter(a, b))
