    if len(negative) % 2 == 1:
        # Odd number of negatives, exclude the one with smallest absolute value
        # Since they're sorted by value, the last one is the largest negative
        result = [costs[i] for i in negative[:-1]] + [costs[i] for i in positive]
    else:
        # Even number of negatives, include all
        result = [costs[i] for i in negative] + [costs[i] for i in positive]

