n = int(input())

class Item:
    def __init__(self, index, t, d, p):
        self.index = index
        self.t = t
        self.d = d
        self.p = p
        self.saved = False

items = []
for i in range(n):
    t, d, p = map(int, input().split())
    if t < d:
        items.append(Item(i + 1, t, d, p))

# Sort by time to save (t)
items.sort(key=lambda x: x.t)

# Dynamic programming to find maximum value
# dp[i][j] = maximum value when considering first i items and total time j
# Since max t is 20 and max items is 100, max total time = 20*100 = 2000
# We need to track both total time and maximum value

# dp[time] = (max_value, items_saved)
# We'll use a dictionary to track state: {time: (value, items_saved)}

# Initial state: time 0, value 0, no items saved
states = {0: (0, [])}

# Process each item
for item in items:
    new_states = {}
    for time, (value, items_saved) in states.items():
        # Option 1: don't save this item
        if time not in new_states or new_states[time][0] < value:
            new_states[time] = (value, items_saved)

        # Option 2: save this item if time + item.t <= item.d
        new_time = time + item.t
        if new_time <= item.d and new_time not in new_states:
            new_states[new_time] = (value + item.p, items_saved + [item.index])

    # Merge states (keep the one with higher value for each time)
    for time, (value, items_saved) in new_states.items():
        if time not in states or states[time][0] < value:
            states[time] = (value, items_saved)

# Find the maximum value
max_value = 0
best_items = []
for time, (value, items_saved) in states.items():
    if value > max_value:
        max_value = value
        best_items = items_saved

# Output results
print(max_value)
print(len(best_items))
print(' '.join(map(str, best_items)))
"}

