import sys

def is_isolated(grid, n, m, i, j):
    """Check if cell (i,j) is isolated initially"""
    # Convert to 0-indexed
    i -= 1
    j -= 1

    # Check all 4 adjacent cells
    for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
        ni, nj = i + dx, j + dy
        if 0 <= ni < n and 0 <= nj < m:
            if grid[ni][nj] == grid[i][j]:
                return False
    return True

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    t = int(next(it))

    grid = []
    for _ in range(n):
        row = next(it)
        grid.append(row)

    out_lines = []

    for _ in range(t):
        i = int(next(it))
        j = int(next(it))
        p = int(next(it))

        if p == 0:
            # Initial state
            out_lines.append(grid[i-1][j-1])
        else:
            if is_isolated(grid, n, m, i, j):
                # Isolated, stays the same
                out_lines.append(grid[i-1][j-1])
            else:
                # Not isolated, flips once
                out_lines.append('1' if grid[i-1][j-1] == '0' else '0')

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
"}

