        # dp[i][j] = 1 + dp[i-1][j-1] if j > 1 else 1
        dp = [[0] * (k + 1) for _ in range(n + 1)]

        # Base cases: dp[0][j] = 1 for all j (starting at position 0 with decay age j)
        for j in range(1, k + 1):
            dp[0][j] = 1

        for i in range(1, n + 1):
            for j in range(1, k + 1):
                if j == 1:
                    dp[i][j] = 1  # No copy produced
                else:
                    dp[i][j] = (1 + dp[i-1][j-1]) % MOD

        print(dp[n][k])

