    MOD = 10**9 + 7
    t = int(input())

    for _ in range(t):
        n, k = map(int, input().split())

        # f(n, k) is the number of particles
        # f(n, 0) = 1
        # f(n, 1) = f(n-1, 1)
        # f(n, k) = f(n-1, k) + f(n-1, k-1) for k > 1

        # Use DP with memoization
        memo = {}

        def dp(p, decay):
            if (p, decay) in memo:
                return memo[(p, decay)]

            if decay == 0:
                return 1
            if decay == 1:
                # No copy produced, only original continues
                res = dp(p - 1, decay)
            else:
                # Original continues and copy is produced
                res = (dp(p - 1, decay) + dp(p - 1, decay - 1)) % MOD

            memo[(p, decay)] = res
            return res

        print(dp(n, k))

solve()
