import sys

def count_ways(N, denominations):
    """Count number of ways to make change for N with given denominations"""
    ways = 0
    for a in range(N + 1):
        remainder = N - a
        if remainder < 0:
            continue
        for d in denominations:
            if d == 0:
                continue
            if remainder % d == 0:
                ways += 1
                break
    return ways

def solve():
    A = int(sys.stdin.readline())

    # We'll use denominations [1, 2]
    # Number of ways = floor(N/2) + 1
    # So we set N = A * 2 - 1
    N = A * 2 - 1
    M = 2
    denominations = [1, 2]

    print(f"{N} {M}")
    print(" ".join(map(str, denominations)))

if __name__ == "__main__":
    solve()
