import sys

def get_divisors(n):
    """Return all divisors of n (n >= 1)"""
    if n == 1:
        return []
    divisors = set()
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    if n >= 2:
        divisors.add(n)
    return sorted(divisors)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    original_total = sum(a)
    min_total = original_total

    for i in range(n):
        ai = a[i]
        divisors = get_divisors(ai)

        for x in divisors:
            # We reduce machine i by x times
            # We increase some machine j by x times
            for j in range(n):
                if j != i:
                    aj = a[j]
                    # Calculate new total
                    change_i = ai/x - ai
                    change_j = aj*x - aj
                    new_total = original_total + change_i + change_j

                    if new_total < min_total:
                        min_total = new_total

    print(min_total)

if __name__ == "__main__":
    solve()
"}

