def transform(arr):
    """Transform array to maximize product"""
    # Convert negatives to positives
    converted = []
    for num in arr:
        if num < 0:
            converted.append(-num - 1)  # -(-3) - 1 = 3 - 1 = 2
        elif num == 0:
            converted.append(0)
        else:
            converted.append(num)  # positive, convert to negative later

    # Count positives and negatives in converted array
    pos_count = sum(1 for num in converted if num > 0)
    neg_count = sum(1 for num in converted if num < 0)
    zeros = sum(1 for num in converted if num == 0)

    # Strategy:
    # - If n is even, convert all positives to negatives
    # - If n is odd, keep one positive
    # - Output in any order

    if n % 2 == 0:
        # Convert all positives to negatives
        for i in range(len(converted)):
            if converted[i] > 0:
                converted[i] = -converted[i] - 1
    else:
        # Keep one positive, convert the rest
        for i in range(len(converted)):
            if converted[i] > 0 and pos_count > 1:
                converted[i] = -converted[i] - 1
                pos_count -= 1

    # Return in any order - just return the list as is
    return converted

