def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False

    sqrt_n = int(n ** 0.5) + 1
    for i in range(3, sqrt_n, 2):
        if n % i == 0:
            return False
    return True

def get_prime_factors(n):
    """Return distinct prime factors of n in ascending order."""
    factors = set()

    # Check for even factor
    if n % 2 == 0:
        factors.add(2)
        while n % 2 == 0:
            n //= 2

    # Check for odd factors
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            factors.add(i)
            while n % i == 0:
                n //= i

    # If remaining n is prime
    if n > 1:
        factors.add(n)

    return sorted(factors)

def solve():
    t = int(input())
    for _ in range(t):
        n = int(input())

        # Get distinct prime factors
        prime_factors = get_prime_factors(n)

        # If no prime factors (shouldn't happen for n > 1)
        if not prime_factors:
            print(1)
            print(n)
            continue

        # Build the sequence
        sequence = [prime_factors[0]]
        current = prime_factors[0]

        for factor in prime_factors[1:]:
            current *= factor
            sequence.append(current)

        # Output
        print(len(sequence))
        print(' '.join(map(str, sequence)))

solve()
