def solve():
    n = int(input())
    s = input().strip()

    len_s = len(s)

    # DP[i][open][pos][matched] = count
    # i: position in sequence (0 to 2n)
    # open: number of unmatched '('
    # pos: current position in s (0 to len(s))
    # matched: whether we've already matched s (0 or 1)

    # Initialize: at position 0, 0 open, 0 matched, pos 0
    dp = [[[0] * 2 for _ in range(len_s + 1) for _ in range(n + 1)] for _ in range(2 * n + 1)]
    dp[0][0][0][0] = 1

    for i in range(2 * n):
        for open_count in range(n + 1):
            for pos in range(len_s + 1):
                for matched in range(2):
                    if dp[i][open_count][pos][matched] == 0:
                        continue

                    # Try adding '('
                    if open_count < n:
                        new_open = open_count + 1
                        new_pos = pos
                        new_matched = matched

                        # Check if we're trying to match s
                        if pos < len_s:
                            if s[pos] == '(':
                                new_pos = pos + 1
                            else:
