import sys

def solve():
    n, k = map(int, sys.stdin.readline().split())

    # Generate sets using the pattern: {i, i+1, i+2, i+4}
    # First set: i = 1 → {1, 2, 3, 5}
    # Second set: i = 7 → {7, 8, 9, 11}
    # Third set: i = 13 → {13, 14, 15, 17}
    # Fourth set: i = 19 → {19, 20, 21, 23}
    # And so on...

    # The pattern: start with 1, then add 6 (since 2+4=6), then add 6, etc.
    # So the starting i for set j is 1 + 6*j

    result = []
    for j in range(n):
        i = 1 + 6 * j
        set_elements = [k * i, k * (i+1), k * (i+2), k * (i+4)]
        result.append(set_elements)

    # Find the maximum number
    max_num = max(max(s) for s in result)

    # Output the results
    print(max_num)
    for s in result:
        print(" ".join(map(str, s)))

if __name__ == "__main__":
    solve()
