import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve(n, k):
    # For set i, use: k * (7 + i*4), k * (8 + i*4), k * (9 + i*4), k * (11 + i*4)
    results = []

    for i in range(n):
        a1 = k * (7 + 4 * i)
        a2 = k * (8 + 4 * i)
        a3 = k * (9 + 4 * i)
        a4 = k * (11 + 4 * i)

        # Verify gcd properties
        s = {a1, a2, a3, a4}
        for x in s:
            for y in s:
                if x != y:
                    if gcd(x, y) != k:
                        raise ValueError(f"Invalid set: {x}, {y} has gcd={gcd(x, y)} != {k}")

        results.append((a1, a2, a3, a4))

    return results

def main():
    import sys
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k = int(data[0]), int(data[1])

    sets = solve(n, k)

    # Calculate minimal m: max element in last set
    m = max(sets[-1])

    print(m)

    for s in sets:
        print(" ".join(str(x) for x in s))

if __name__ == "__main__":
    main()
