def mobius(n):
    """Calculate the Möbius function for all numbers up to n"""
    mu = [1] * (n + 1)
    is_square_free = [True] * (n + 1)
    for i in range(2, n + 1):
        if i * i > n:
            break
        for j in range(i * i, n + 1, i * i):
            is_square_free[j] = False

    mu[1] = 1
    for i in range(2, n + 1):
        if i * i > n:
            break
        # i is a prime
        for j in range(i, n + 1, i):
            mu[j] *= -1
        for j in range(i * i, n + 1, i * i):
            mu[j] = 0

    return mu

def solve():
    MOD = 10**9 + 7
    n = int(input())
    a = list(map(int, input().split()))

    # Count frequency of each number
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    max_val = max(a)
    # Calculate Möbius function
    mu = mobius(max_val)

    result = 0
    # For each d, count elements divisible by d
    for d in range(1, max_val + 1):
        cnt = 0
        for m in range(d, max_val + 1, d):
            cnt += freq.get(m, 0)
        f_d = pow(2, cnt, MOD) - 1
        result = (result + mu[d] * f_d) % MOD

    print(result)

solve()
