import sys

def mobius_function(max_val):
    """Return the Möbius function for all numbers up to max_val"""
    mu = [1] * (max_val + 1)
    is_prime = [True] * (max_val + 1)
    prime_factors = {}  # To store smallest prime factor for each number

    for i in range(2, max_val + 1):
        if is_prime[i]:
            # i is prime
            prime_factors[i] = i
            for j in range(i, max_val + 1, i):
                is_prime[j] = False
                if j // i % i == 0:
                    # j has at least one square factor of i
                    mu[j] = 0
                else:
                    # j has exactly one factor of i
                    mu[j] *= -1

    return mu

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    max_a = max(a)

    # Count frequency of each number
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # Count how many elements are divisible by each d
    cnt = [0] * (max_a + 1)
    for d in range(1, max_a + 1):
        for num in freq:
            if num % d == 0:
                cnt[d] += freq[num]

    # Precompute powers of 2
    pow2 = [1] * (n + 1)
    for i in range(1, n + 1):
        pow2[i] = (pow2[i-1] * 2) % (10**9 + 7)

    # Compute f(d) = 2^cnt[d] - 1
    f = [0] * (max_a + 1)
    for d in range(1, max_a + 1):
        f[d] = (pow2[cnt[d]] - 1) % (10**9 + 7)

    # Compute Möbius function
    mu = mobius_function(max_a)

    # Inclusion-exclusion with Möbius function
    answer = 0
    for d in range(1, max_a + 1):
        answer = (answer + mu[d] * f[d]) % (10**9 + 7)

    print(answer)

if __name__ == "__main__":
    solve()
"}

