for i in range(1, min(len1, len2) + 1):
    if len1 % i == 0 and len2 % i == 0:
        common_lengths.append(i)

# For each common length, check if the substring is a divisor of both strings
common_divisors = set()
for length in common_lengths:
    # Check if the substring of this length is a divisor of both strings
    candidate = s1[:length]
    if len1 % length == 0 and len2 % length == 0:
        # Check if candidate repeated len1/length times equals s1
        if candidate * (len1 // length) == s1:
            # Check if candidate repeated len2/length times equals s2
            if candidate * (len2 // length) == s2:
                common_divisors.add(candidate)

print(len(common_divisors))
